int sensor = A0;  // Pin analógico donde se conecta el sensor
int valor;       // Variable para almacenar la lectura

void setup() {
    Serial.begin(9600); // Inicializa comunicación serie a 9600 baudios
}

void loop() {
    valor = analogRead(sensor); // Lee el valor analógico (0 a 1023)
    Serial.println(valor);      // Imprime el valor en la consola serie
    delay(500);                 // Muestrea la lectura cada medio segundo
}
